16	std::vector<std::unique_ptr<TmpBufDesc>> CalcPolygammaTmpSizeV2(const AscNode &node) {
17	  // PolyGamma requires tmp buffer size equal to the size of the source tensor (x)
18	  auto node_inputs = node.inputs;
19	  GE_ASSERT_TRUE(node_inputs.Size() > 0, "Node %s[%s] inputs size is 0.", node.GetTypePtr(), node.GetNamePtr());
20	
21	  // Get input size using the same method as GetInputDataSizeTmpBuffer
22	  const auto input_size = GetInputSize(node_inputs);
23	  uint32_t input_id = GetNonScalarAxisId(node_inputs);
24	  if (input_id == UINT32_MAX) {
25	    input_id = 0;  // Use first input (x) for PolyGamma
26	  }
27	  const auto data_type_size = GetSizeByDataType(node_inputs[input_id].attr.dtype);
28	
29	  GELOGD("Node %s[%s] inputs[%u] data type size is: %d", node.GetTypePtr(), node.GetNamePtr(), input_id,
30	         data_type_size);
31	
32	  // Calculate total tmp buffer size = data_type_size * input_size
33	  const Expression total_size = Symbol(data_type_size) * input_size;
34	
35	  GELOGD("Node %s[%s] temp buffer size: %s (equal to input tensor size)", node.GetTypePtr(), node.GetNamePtr(),
36	         total_size.Str().get());
37	
38	  return GetTmpBuffer(total_size);
39	}
40	}  // namespace ascir
41	}  // namespace af
