29	bool HasSimtArity(const AscNode &node, size_t input_count) {
30	  AscNode &mutable_node = const_cast<AscNode &>(node);
31	  return mutable_node.inputs.Size() == input_count && mutable_node.outputs().size() == 1UL;
32	}
33	
34	ge::DataType GetSimtInputDtype(const AscNode &node) {
35	  return const_cast<AscNode &>(node).inputs[0].attr.dtype;
36	}
37	
38	ge::DataType GetSimtOutputDtype(const AscNode &node) {
39	  return const_cast<AscNode &>(node).outputs[0].attr.dtype;
40	}
41	
42	bool HasSameSimtUnaryDtype(const AscNode &node) {
43	  return HasSimtArity(node, 1UL) && GetSimtInputDtype(node) == GetSimtOutputDtype(node);
44	}
45	
46	bool HasSameSimtBinaryDtype(const AscNode &node) {
47	  AscNode &mutable_node = const_cast<AscNode &>(node);
48	  if (!HasSimtArity(node, 2UL)) {
49	    return false;
50	  }
51	  const ge::DataType dtype = GetSimtOutputDtype(node);
52	  return mutable_node.inputs[0].attr.dtype == dtype && mutable_node.inputs[1].attr.dtype == dtype;
53	}
54	
55	bool IsSimtFloatDtype(ge::DataType dtype) {
56	  return dtype == DT_FLOAT || dtype == DT_FLOAT16 || dtype == DT_BF16;
57	}
58	
59	const char *GetSimtDtypeName(ge::DataType dtype) {
60	  static constexpr std::pair<ge::DataType, const char *> kDtypeNames[] = {
61	      {DT_FLOAT, "float"},     {DT_FLOAT16, "half"},  {DT_BF16, "bfloat16_t"}, {DT_INT8, "int8_t"},
62	      {DT_UINT8, "uint8_t"},   {DT_INT16, "int16_t"}, {DT_UINT16, "uint16_t"}, {DT_INT32, "int32_t"},
63	      {DT_UINT32, "uint32_t"}, {DT_INT64, "int64_t"}, {DT_UINT64, "uint64_t"}, {DT_BOOL, "bool"},
64	  };
65	  for (const auto &entry : kDtypeNames) {
66	    if (entry.first == dtype) {
67	      return entry.second;
68	    }
69	  }
70	  return nullptr;
71	}
72	
73	bool HasSameSimtBinaryArithmeticDtype(const AscNode &node) {
74	  return HasSameSimtBinaryDtype(node) && GetSimtOutputDtype(node) != DT_BOOL &&
75	         GetSimtDtypeName(GetSimtOutputDtype(node)) != nullptr;
76	}
