84	ge::graphStatus GenerateSimtFloatBinaryExpr(const std::string &op, const std::vector<std::string> &inputs,
85	                                            std::string &expr) {
86	  expr = "(static_cast<float>(" + inputs[0] + ") " + op + " static_cast<float>(" + inputs[1] + "))";
87	  return ge::GRAPH_SUCCESS;
88	}
89	
90	ge::graphStatus GenerateSimtFloatUnaryExpr(const std::string &api, const std::vector<std::string> &inputs,
91	                                           std::string &expr) {
92	  expr = "AscendC::Simt::" + api + "(static_cast<float>(" + inputs[0] + "))";
93	  return ge::GRAPH_SUCCESS;
94	}
