96	bool IsSimtFloatToIntPair(const AscNode &node) {
97	  static constexpr std::pair<ge::DataType, ge::DataType> kPairs[] = {
98	      {DT_FLOAT, DT_INT64},   {DT_FLOAT, DT_INT32},  {DT_FLOAT, DT_INT16},   {DT_FLOAT16, DT_INT16},
99	      {DT_FLOAT16, DT_INT32}, {DT_FLOAT16, DT_INT8}, {DT_FLOAT16, DT_UINT8}, {DT_BF16, DT_INT32},
100	  };
101	  const std::pair<ge::DataType, ge::DataType> pair{GetSimtInputDtype(node), GetSimtOutputDtype(node)};
102	  return std::find(std::begin(kPairs), std::end(kPairs), pair) != std::end(kPairs);
103	}
104	
105	ge::graphStatus GenerateSimtFloatToIntExpr(const AscNode &node, const std::vector<std::string> &inputs,
106	                                           const std::string &round_mode, std::string &expr) {
107	  const ge::DataType output_dtype = GetSimtOutputDtype(node);
108	  const char *output_type = GetSimtDtypeName(output_dtype);
109	  GE_ASSERT_NOTNULL(output_type, "Node %s[%s] has unsupported SIMT output dtype %d", node.GetTypePtr(),
110	                    node.GetNamePtr(), static_cast<int32_t>(output_dtype));
111	  const char *intermediate_type = output_dtype == DT_INT64 ? "int64_t" : "int32_t";
112	  const std::string intermediate_expr = std::string("AscendC::Simt::Cast<") + intermediate_type +
113	                                        ", float, AscendC::RoundMode::" + round_mode + ">(" + "static_cast<float>(" +
114	                                        inputs[0] + "))";
115	  expr = output_dtype == DT_INT32 || output_dtype == DT_INT64
116	             ? intermediate_expr
117	             : std::string("static_cast<") + output_type + ">(" + intermediate_expr + ")";
118	  return ge::GRAPH_SUCCESS;
119	}
