TEST_F(TestBackendChebyshevPolynomialTStoreE2e, ChebyshevPolynomialTStoreE2eCodegen) {
  bool gen_success = true;
  std::string chebyshev_tiling_stub = R"(
#define REGISTER_TILING_DEFAULT(tiling)
#define GET_TILING_DATA(t, tiling)  AutofuseTilingData t = *(AutofuseTilingData*)tiling;
)";

  std::map<std::string, std::string> chebyshev_shape_info({{"s0", "stub_s0"}, {"s1", "stub_s1"}});
  auto graph = ascir::ShareGraph::ChebyshevPolynomialTStoreFusedGraph(2);
  std::vector<std::string> chebyshev_parts = splitString(KERNEL_SRC_LIST, ':');
  const std::string &kernel_src_file_name = chebyshev_parts[0];
  const std::string &tiling_src_file_name = chebyshev_parts[1];
  const std::string &tiling_data_src_file_name = chebyshev_parts[2];

  try {
    optimize::Optimizer chebyshev_optimizer(optimize::OptimizerOptions{});
    codegen::Codegen chebyshev_codegen(codegen::CodegenOptions{});

    std::fstream chebyshev_kernel_stream(kernel_src_file_name, std::ios::out);
    std::fstream chebyshev_tiling_stream(tiling_src_file_name, std::ios::out);
    std::fstream chebyshev_data_stream(tiling_data_src_file_name, std::ios::out);

    std::vector<::ascir::ScheduledResult> chebyshev_schedules;
    ascir::FusedScheduledResult chebyshev_fused_result;
    chebyshev_fused_result.node_idx_to_scheduled_results.push_back(chebyshev_schedules);
    EXPECT_EQ(chebyshev_optimizer.Optimize(graph, chebyshev_fused_result), 0);
    codegen::CodegenResult chebyshev_result;
    EXPECT_EQ(chebyshev_codegen.Generate(chebyshev_shape_info, chebyshev_fused_result, chebyshev_result), 0);
    EXPECT_NE(chebyshev_result.kernel.find("ChebyshevPolynomialTExtend"), std::string::npos);
    chebyshev_kernel_stream << chebyshev_tiling_stub << RemoveSubDirInclude(chebyshev_result.kernel);
    chebyshev_tiling_stream << chebyshev_result.tiling;
    chebyshev_data_stream << chebyshev_result.tiling_data;
  } catch (...) {
    gen_success = false;
  }

  EXPECT_EQ(gen_success, true);
}
